def close_parenthesis(seq):
    stack = []
    closing_parenthesis = {'{', '}', '[', ']'}

    for s in seq:
        if s[0] in closing_parenthesis:
            stack.append(s)
            continue

        # make sure ']' is at the last character of input
        if len(stack) > 1:
            if s[0] == ')' and s[-1] == '[' and (stack[-2]!= ']'):
                raise ValueError("Failed to close " + s)
            while s[0] == ')' and s[-1] in closing_parenthesis and stack[-1] == '(':
                stack.pop()
        else:
            stack.append(s)

    # closing parens should have a root ']'
    while stack:
        if stack[-1]!= ']':
            raise ValueError("Failed to close " + stack[-1])
        stack.pop()

    return "".join(stack)

